/**
 * Deep-merges user preference overrides onto app defaults.
 * Nested plain objects are merged key-by-key; arrays and primitives
 * in `overrides` replace the corresponding value in `defaults` wholesale.
 * `undefined` values in overrides are ignored (so a key can't accidentally
 * erase a default); `null` is treated as an explicit override value.
 */
function mergeUserPrefs(defaults, overrides) {
  if (!isPlainObject(defaults) || !isPlainObject(overrides)) {
    return overrides === undefined ? defaults : overrides;
  }

  const result = { ...defaults };
  for (const key of Object.keys(overrides)) {
    const overrideVal = overrides[key];
    if (overrideVal === undefined) continue;
    result[key] = mergeUserPrefs(defaults[key], overrideVal);
  }
  return result;
}

function isPlainObject(val) {
  return typeof val === 'object' && val !== null && !Array.isArray(val);
}

// --- check ---
function demo() {
  const defaults = {
    theme: { mode: 'light', accent: 'blue' },
    notifications: { email: true, sms: false },
    tags: ['a', 'b'],
  };

  // partial nested override preserves sibling defaults
  const r1 = mergeUserPrefs(defaults, { theme: { mode: 'dark' } });
  console.assert(r1.theme.mode === 'dark' && r1.theme.accent === 'blue', 'nested merge failed');

  // arrays replace, not concat
  const r2 = mergeUserPrefs(defaults, { tags: ['c'] });
  console.assert(r2.tags.length === 1 && r2.tags[0] === 'c', 'array replace failed');

  // undefined override key is ignored, doesn't clobber default
  const r3 = mergeUserPrefs(defaults, { theme: undefined });
  console.assert(r3.theme.mode === 'light', 'undefined-override guard failed');

  // explicit null is honored as an override value
  const r4 = mergeUserPrefs(defaults, { notifications: { email: null } });
  console.assert(r4.notifications.email === null, 'explicit null failed');

  console.log('mergeUserPrefs: all checks passed');
}

demo();
