/**
 * Fetch a URL, retrying on network errors and 5xx/429 responses with
 * exponential backoff + jitter. 4xx responses are treated as final
 * (retrying a bad request just repeats the same failure).
 */
async function retryFetch(
  url,
  {
    retries = 3,
    baseDelayMs = 300,
    retryOn = (res, err) => !!err || res.status >= 500 || res.status === 429,
    fetchOptions,
  } = {}
) {
  let attempt = 0;
  while (true) {
    let res, err;
    try {
      res = await fetch(url, fetchOptions);
    } catch (e) {
      err = e;
    }

    const shouldRetry = attempt < retries && retryOn(res, err);
    if (!shouldRetry) {
      if (err) throw err;
      return res;
    }

    const delay = baseDelayMs * 2 ** attempt + Math.random() * baseDelayMs;
    await new Promise((r) => setTimeout(r, delay));
    attempt++;
  }
}

// --- self-check ---
async function demo() {
  const assert = require('assert');

  // recovers after transient failures
  let calls = 0;
  global.fetch = async () => {
    calls++;
    if (calls < 3) throw new Error('network down');
    return { ok: true, status: 200 };
  };
  const res = await retryFetch('http://x', { baseDelayMs: 1 });
  assert.strictEqual(calls, 3);
  assert.strictEqual(res.status, 200);

  // exhausts retries then throws
  calls = 0;
  global.fetch = async () => {
    calls++;
    throw new Error('down');
  };
  await assert.rejects(() => retryFetch('http://x', { retries: 2, baseDelayMs: 1 }));
  assert.strictEqual(calls, 3); // initial attempt + 2 retries

  // 4xx is not retried
  calls = 0;
  global.fetch = async () => {
    calls++;
    return { ok: false, status: 404 };
  };
  const res404 = await retryFetch('http://x', { retries: 5, baseDelayMs: 1 });
  assert.strictEqual(calls, 1);
  assert.strictEqual(res404.status, 404);

  console.log('all checks passed');
}
demo();
```

